-- Harden all Domain scores: only server-validated 5-round submissions may be stored.
-- Values cannot be forged by changing client score, price or guesses in a JSON payload.
-- The public dataset remains visible on Crilo; this prevents raw database score edits,
-- not cheating by researching known prices.
CREATE SCHEMA IF NOT EXISTS crilo_internal;
REVOKE ALL ON SCHEMA crilo_internal FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS crilo_internal.domain_answers (
  domain text PRIMARY KEY,
  price numeric(16,2) NOT NULL CHECK (price>0),
  kind text NOT NULL CHECK (kind IN ('documented_sale','crilo_estimate'))
);
REVOKE ALL ON crilo_internal.domain_answers FROM PUBLIC,anon,authenticated;
