ALTER TABLE public.game_scores ADD COLUMN IF NOT EXISTS is_verified boolean NOT NULL DEFAULT false;
REVOKE INSERT,UPDATE,DELETE ON public.game_scores FROM PUBLIC,anon,authenticated;
REVOKE ALL(score,details,created_at,user_id,game_key,id) ON public.game_scores FROM authenticated;
-- Scoring is server-authoritative; direct PostgREST score INSERT is forbidden.
CREATE OR REPLACE FUNCTION public.crilo_submit_domain_score(p_rounds jsonb)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $submit$
DECLARE
 uid uuid:=auth.uid();
 entry jsonb; dom text; slider integer; actual numeric; kind text;
 raw numeric; guess numeric; rat numeric; points integer; score_total bigint:=0;
 normalized jsonb:='[]'::jsonb; used text[]:=ARRAY[]::text[];
 sale_count integer:=0; estimate_count integer:=0;
 row_count integer:=0; saved_id bigint;
BEGIN
 IF uid IS NULL OR auth.role() <> 'authenticated' THEN
   RAISE EXCEPTION 'Sign in required to save Domain scores' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=uid)
   OR EXISTS(SELECT 1 FROM public.crilo_banned_accounts WHERE user_id=uid) THEN
   RAISE EXCEPTION 'A valid, active Crilo account is required' USING ERRCODE='42501';
 END IF;
 IF p_rounds IS NULL OR jsonb_typeof(p_rounds)<>'array' OR jsonb_array_length(p_rounds)<>5 THEN
   RAISE EXCEPTION 'Five completed Domain rounds required' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,744280));
 IF (SELECT count(*) FROM public.game_scores
     WHERE user_id=uid AND game_key='domain' AND is_verified
       AND created_at > now()-interval '1 hour')>=40
    OR EXISTS(SELECT 1 FROM public.game_scores
      WHERE user_id=uid AND game_key='domain' AND is_verified
        AND created_at > now()-interval '5 seconds') THEN
   RAISE EXCEPTION 'Domain score submission limit reached; please try again later' USING ERRCODE='23514';
 END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_rounds) LOOP
   IF jsonb_typeof(entry)<>'object'
      OR jsonb_typeof(entry->'domain')<>'string'
      OR jsonb_typeof(entry->'slider')<>'number'
      OR (entry->>'slider') !~ '^[0-9]{1,4}$' THEN
     RAISE EXCEPTION 'Invalid Domain round data' USING ERRCODE='22023';
   END IF;
   dom:=lower(btrim(entry->>'domain'));
   slider:=(entry->>'slider')::integer;
   IF slider<0 OR slider>1000 OR dom=ANY(used) THEN
     RAISE EXCEPTION 'Repeated domain or invalid slider position' USING ERRCODE='22023';
   END IF;
   SELECT a.price,a.kind INTO actual,kind
     FROM crilo_internal.domain_answers a WHERE a.domain=dom;
   IF NOT FOUND THEN
     RAISE EXCEPTION 'Unknown domain in submitted round' USING ERRCODE='22023';
   END IF;
   IF kind='documented_sale' THEN sale_count:=sale_count+1;
   ELSIF kind='crilo_estimate' THEN estimate_count:=estimate_count+1; END IF;
   -- Exactly the 0-1000 log slider and price snapping rules used by Domain UI.
   raw:=power(10::numeric,(slider::numeric/1000)*log(250000000::numeric));
   guess:=CASE
    WHEN raw<10 THEN round(raw*100)/100
    WHEN raw<100 THEN round(raw)
    WHEN raw<1000 THEN round(raw/10)*10
    WHEN raw<10000 THEN round(raw/100)*100
    WHEN raw<100000 THEN round(raw/1000)*1000
    WHEN raw<1000000 THEN round(raw/10000)*10000
    WHEN raw<10000000 THEN round(raw/100000)*100000
    ELSE round(raw/1000000)*1000000 END;
   rat:=greatest(guess,actual)/greatest(.01::numeric,least(guess,actual));
   points:=greatest(0,least(1000,round((1000*exp(-1.35::numeric*log(rat)))::numeric)))::integer;
   score_total:=score_total+points;
   used:=array_append(used,dom); row_count:=row_count+1;
   normalized:=normalized||jsonb_build_array(jsonb_build_object(
      'domain',dom,'guess',guess,'actual',actual,'score',points,'type',kind,'slider',slider));
 END LOOP;
 IF row_count<>5 OR sale_count<>3 OR estimate_count<>2 OR score_total<0 OR score_total>5000 THEN
   RAISE EXCEPTION 'Invalid Domain round distribution' USING ERRCODE='22023';
 END IF;
 INSERT INTO public.game_scores(user_id,game_key,score,details,is_verified)
 VALUES(uid,'domain',score_total,jsonb_build_object('rounds',normalized),true)
 RETURNING id INTO saved_id;
 RETURN score_total;
END
$submit$;
REVOKE ALL ON FUNCTION public.crilo_submit_domain_score(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crilo_submit_domain_score(jsonb) TO authenticated;
